pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 extra) internal {
        vm.assume(extra > 0 && extra <= 10**18);
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        uint balBefore = address(c).balance;
        bool reverted;
        try c.withdraw(balBefore + extra) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted &&
            c.depositsCount() == countBefore &&
            address(c).balance == balBefore);
    }

    function testFuzz_run(uint256 extra) public {
        _run(extra);
    }

    receive() external payable {}
}
